## Usage Examples

### Minimal SFD Training Loop

```zig
const std = @import("std");
const optimizer_lib = @import("optimizer.zig");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const param_size: usize = 1024;

    var params = try optimizer_lib.Tensor.zeros(allocator, &[_]usize{param_size});
    defer params.deinit();
    try params.fillRandomNormal(0.0, 0.02);

    var optimizer = try optimizer_lib.SFD.init(allocator, param_size);
    defer optimizer.deinit();

    var scheduler = optimizer_lib.LRScheduler.init(
        allocator, .cosine_annealing, 1e-3, 100, 10_000
    );

    var step: usize = 0;
    while (step < 10_000) : (step += 1) {
        // Compute gradients (user-provided)
        var grads = try computeGradients(allocator, &params);
        defer grads.deinit();

        const lr = try scheduler.getLearningRate(null);
        try optimizer.update(&grads, &params, lr);
    }

    try optimizer.saveState("model.bin");
}
```

### SophiaSOAP with Mixed Precision

```zig
const layer_dims = [_]usize{
    [_]usize{ 768, 768 },
    [_]usize{ 768, 3072 },
    [_]usize{ 3072, 768 },
};

var sophia_opt = try SophiaSOAPOptimizer.init(
    allocator, total_params, &layer_dims, .{}
);
defer sophia_opt.deinit();

const mp_config = MixedPrecisionConfig{};
var mp_trainer = try MixedPrecisionTrainer.init(allocator, weight_shapes, mp_config);
defer mp_trainer.deinit();

var step: usize = 0;
while (step < total_steps) : (step += 1) {
    const lr = try scheduler.getLearningRate(null);

    try sophia_opt.update(&gradients, &params, &activations, lr);
    mp_trainer.loss_scaler.update(gradient_slice);

    if (step % mp_config.gradient_accumulation_steps == 0) {
        try mp_trainer.updateWeights(lr);
    }
}
```

